var e=[{id:"inscription",label:"Inscription",items:[{id:"comment-inscrire",question:"Comment inscrire un jeune \xE0 Alegria 2027 ?",answer:"Rendez-vous sur la page \xAB Inscription des jeunes \xBB. La page \xAB Devenir famille d\u2019accueil \xBB sert uniquement \xE0 proposer un h\xE9bergement pour le rassemblement."},{id:"ouverture-inscriptions",question:"Quand ouvrent les inscriptions ?",answer:"La date d'ouverture des inscriptions n'est pas encore fix\xE9e. Elle sera annonc\xE9e sur cette page et relay\xE9e par votre dioc\xE8se ou groupe MEJ."},{id:"modifier-inscription",question:"Puis-je modifier une inscription apr\xE8s l\u2019avoir envoy\xE9e ?",answer:"Les modalit\xE9s de modification seront pr\xE9cis\xE9es dans la confirmation d'inscription. Contactez l'\xE9quipe d'organisation en cas de besoin urgent."}]},{id:"familles-accueil",label:"Familles d\u2019accueil",items:[{id:"proposer-accueil",question:"Comment devenir famille d\u2019accueil ?",answer:"Compl\xE9tez le formulaire \xAB Devenir famille d\u2019accueil \xBB avec vos coordonn\xE9es, l\u2019adresse de l\u2019h\xE9bergement, vos capacit\xE9s et vos contraintes. La coordination examinera votre proposition et vous recontactera."},{id:"affectation-jeunes",question:"Dois-je inscrire ou choisir les jeunes que je vais accueillir ?",answer:"Non. Vous proposez uniquement un accueil pour votre foyer. L\u2019\xE9quipe de coordination valide les propositions et r\xE9alise les affectations des jeunes dans les familles."},{id:"modalites-accueil",question:"Quelles nuits, quels repas et quels d\xE9placements faut-il pr\xE9voir ?",answer:"Ces modalit\xE9s seront confirm\xE9es avec la coordination. Vous pouvez pr\xE9ciser vos possibilit\xE9s et vos contraintes dans le formulaire."},{id:"modifier-accueil",question:"Comment modifier ma proposition d\u2019accueil ?",answer:"Contactez l\u2019organisation en indiquant le nom et les coordonn\xE9es utilis\xE9s dans votre proposition. Aucun e-mail automatique de confirmation n\u2019est envoy\xE9."}]},{id:"age-profils",label:"\xC2ge et profils",items:[{id:"age-concerne",question:"\xC0 partir de quel \xE2ge peut-on participer ?",answer:"Alegria 2027 s'adresse principalement aux jeunes de 12 \xE0 18 ans, accompagn\xE9s par des animateurs et responsables. Les familles et b\xE9n\xE9voles adultes sont \xE9galement les bienvenus."},{id:"decouverte-mej",question:"Faut-il d\xE9j\xE0 \xEAtre membre du MEJ pour participer ?",answer:"Cette r\xE8gle n'est pas encore confirm\xE9e. Alegria se veut ouvert \xE0 celles et ceux qui d\xE9couvrent le mouvement comme aux membres d\xE9j\xE0 engag\xE9s."}]},{id:"tarifs",label:"Tarifs",items:[{id:"montant",question:"Quel est le tarif de participation ?",answer:"Les tarifs ne sont pas encore fix\xE9s. Ils seront communiqu\xE9s avant l'ouverture des inscriptions, avec un bar\xE8me adapt\xE9 et des possibilit\xE9s d'aide."},{id:"aide-financiere",question:"Existe-t-il une aide en cas de difficult\xE9 financi\xE8re ?",answer:"Une solidarit\xE9 entre participants est envisag\xE9e. Si le co\xFBt est un frein, contactez l'\xE9quipe d'organisation avant de renoncer \xE0 l'inscription."}]},{id:"transport",label:"Transport",items:[{id:"venir-comment",question:"Comment se rendre \xE0 Saint-\xC9tienne ?",answer:"Le Centre de Congr\xE8s est accessible depuis la gare de Saint-\xC9tienne Ch\xE2teaucreux et par les transports en commun locaux. Le d\xE9tail des modalit\xE9s de transport collectif sera pr\xE9cis\xE9 ult\xE9rieurement."}]},{id:"hebergement",label:"H\xE9bergement",items:[{id:"ou-dormir",question:"O\xF9 seront h\xE9berg\xE9s les participants ?",answer:"Des familles peuvent proposer d\u2019accueillir les jeunes. La coordination organise les affectations et confirme les modalit\xE9s pratiques d\u2019h\xE9bergement."}]},{id:"repas",label:"Repas",items:[{id:"regimes-particuliers",question:"Les r\xE9gimes alimentaires particuliers sont-ils pris en compte ?",answer:"Un espace du formulaire d'inscription permettra de signaler les r\xE9gimes particuliers (allergies, convictions religieuses, v\xE9g\xE9tarien...). Les modalit\xE9s pr\xE9cises seront communiqu\xE9es ult\xE9rieurement."}]},{id:"sante",label:"Sant\xE9",items:[{id:"besoins-specifiques",question:"Comment signaler un besoin de sant\xE9 particulier ?",answer:"Le formulaire d'inscription comportera une rubrique d\xE9di\xE9e aux informations de sant\xE9, trait\xE9e de fa\xE7on confidentielle par l'\xE9quipe sant\xE9 de l'\xE9v\xE9nement."}]},{id:"securite",label:"S\xE9curit\xE9",items:[{id:"encadrement-securite",question:"Quelles sont les mesures de s\xE9curit\xE9 pr\xE9vues ?",answer:"L'organisation met en place une \xE9quipe s\xE9curit\xE9 et sant\xE9 d\xE9di\xE9e, ainsi qu'un encadrement adapt\xE9 \xE0 chaque tranche d'\xE2ge. Le d\xE9tail des dispositifs sera publi\xE9 avant l'\xE9v\xE9nement."}]},{id:"accessibilite",label:"Accessibilit\xE9",items:[{id:"accessibilite-lieu",question:"Le site est-il accessible aux personnes \xE0 mobilit\xE9 r\xE9duite ?",answer:"Les informations d'accessibilit\xE9 du Centre de Congr\xE8s de Saint-\xC9tienne seront v\xE9rifi\xE9es et publi\xE9es sur la page \xAB Lieu et acc\xE8s \xBB. Contactez l'organisation pour tout besoin sp\xE9cifique."}]},{id:"encadrement",label:"Encadrement",items:[{id:"qui-encadre",question:"Qui encadre les jeunes pendant le rassemblement ?",answer:"Les jeunes sont accompagn\xE9s par des animateurs et responsables MEJ, ainsi que par une \xE9quipe de b\xE9n\xE9voles form\xE9s. Les r\xE8gles d'encadrement seront d\xE9taill\xE9es dans le livret pratique."}]},{id:"documents",label:"Documents",items:[{id:"documents-necessaires",question:"Quels documents faut-il pr\xE9parer ?",answer:"La liste pr\xE9cise des documents (autorisation parentale, fiche sanitaire, etc.) sera communiqu\xE9e avec la confirmation d'inscription."}]},{id:"annulation",label:"Annulation",items:[{id:"politique-annulation",question:"Que se passe-t-il en cas d'annulation ?",answer:"La politique d'annulation et de remboursement n'est pas encore d\xE9finie. Elle sera publi\xE9e avant l'ouverture des inscriptions."}]},{id:"contact",label:"Contact",items:[{id:"qui-contacter",question:"Qui contacter en cas de question ?",answer:"Rendez-vous sur la page Contact pour conna\xEEtre les interlocuteurs d\xE9di\xE9s aux familles, aux b\xE9n\xE9voles et aux questions g\xE9n\xE9rales."}]}];export{e as a};
